<?php
$adminView=$page==='admin_invoices';$sql='SELECT i.*,o.product_name,o.reference,o.payment_status,r.state AS payment_state,r.kind AS receivable_kind,r.issued_ts,r.amount_cents AS receivable_amount FROM shop_invoices i JOIN shop_orders o ON o.id=i.order_id LEFT JOIN shop_receivables r ON r.invoice_id=i.id';$args=[];
if(!$adminView){$sql.=' WHERE i.customer_id=?';$args[]=(int)user()['id'];}$invoices=all($sql.' ORDER BY i.id DESC LIMIT 500',$args);
?>
<section class="panel"><?php if(!$invoices):empty_state('package','Noch keine Rechnungen','Neue Bestellungen erhalten eine Rechnung. Hier findest du Zahlungsstatus, PayPal-Zahlungslinks und PDF-Belege.');else: ?>
<div class="table-scroll"><table><thead><tr><th>Rechnung</th><th>Produkt / Bestellung</th><th>Betrag</th><th>Status / Datum</th><th></th></tr></thead><tbody>
<?php foreach($invoices as $invoice):$snapshot=json_decode($invoice['snapshot'],true);$open=$invoice['payment_state']==='open';$status=$invoice['kind']==='cancellation'?'Stornorechnung':($snapshot['sandbox']?'Test – kein Geldfluss':(['open'=>'Offen','paid'=>'Bezahlt','void'=>'Storniert'][$invoice['payment_state']]??'Bezahlt')); ?>
<tr><td><strong><?= e($invoice['number']) ?></strong><?php if($snapshot['sandbox']): ?><small>Testrechnung · kein Geldfluss</small><?php endif;if($adminView): ?><small><?= e($snapshot['buyer']['email']) ?></small><?php endif ?></td><td><?= e($invoice['product_name']) ?><small><?= e($invoice['reference']) ?></small></td><td><?= money($snapshot['tax']['gross_cents']) ?><small>inkl. <?= money($snapshot['tax']['tax_cents']) ?> MwSt.</small></td>
<td><strong><?= e($status) ?></strong><small><?= date_de($invoice['issued_at']) ?></small><?php if($open && shop_now()-(int)$invoice['issued_ts']>=3*86400): ?><small>Zahlungserinnerung: seit mindestens drei Tagen offen.</small><?php endif ?></td>
<td><div class="button-row"><a class="button button-outline button-small" href="<?= $adminView?'/admin':'/konto' ?>/rechnungen?download=<?= (int)$invoice['id'] ?>">PDF herunterladen <?= icon('arrow') ?></a>
<?php if(!$adminView && $open): ?><form method="post"><?= csrf() ?><input type="hidden" name="action" value="invoice_checkout"><input type="hidden" name="invoice_id" value="<?= (int)$invoice['id'] ?>"><button class="button button-teal button-small">Mit PayPal bezahlen</button></form><form method="post"><?= csrf() ?><input type="hidden" name="action" value="payment_refresh"><input type="hidden" name="order_id" value="<?= (int)$invoice['order_id'] ?>"><button class="button button-outline button-small">Zahlungsstatus prüfen</button></form><?php endif ?>
</div></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
